parameters.jsCode:
const alert = $json.body || $json;
const vt = alert.data?.virustotal || {};

// Real VirusTotal alerts have md5/sha1 only; the sha256 is inside the permalink URL
const linkMatch = (vt.permalink || "").match(/\/file\/([a-f0-9]{64})/i);

let rawData = {
  alert_id: alert.id || "WZ-" + Math.floor(1000 + Math.random() * 9000),
  agent_name: alert.agent?.name || "UNKNOWN-AGENT",
  agent_ip: alert.agent?.ip || "0.0.0.0",
  timestamp: alert.timestamp || new Date().toISOString(),
  file_path: vt.source?.file || alert.syscheck?.path || "UNKNOWN",
  sha256: vt.source?.sha256 || (linkMatch ? linkMatch[1] : (vt.sha1 || "UNKNOWN")),
  positives: vt.positives || 0,
  total_engines: vt.total || 0,
  rule_description: alert.rule?.description || "No description"
};

let serialized = JSON.stringify(rawData);

// Mask internal IPs (RFC 1918)
serialized = serialized.replace(/\b(10\.\d{1,3}\.\d{1,3}\.\d{1,3}|192\.168\.\d{1,3}\.\d{1,3}|172\.(1[6-9]|2[0-9]|3[0-1])\.\d{1,3}\.\d{1,3})\b/g, "[INTERNAL_IP_MASKED]");

// Mask the Windows username in paths
serialized = serialized.replace(/C:\\\\Users\\\\[^\\]+/gi, "C:\\\\Users\\\\[CORP_USER_REDACTED]");

return [{ json: JSON.parse(serialized) }];

const staticData = $getWorkflowStaticData('global');
staticData.hashCache = staticData.hashCache || {};

const hash = $json.sha256;
const now = Date.now();
const CACHE_TTL = 7 * 24 * 60 * 60 * 1000; // 7 days in milliseconds

if (staticData.hashCache[hash] && (now - staticData.hashCache[hash].timestamp < CACHE_TTL)) {
  $json.cache_hit = true;
} else {
  $json.cache_hit = false;
  staticData.hashCache[hash] = {
    timestamp: now
  };
}

return [{ json: $json }];

