const geminiParts = $json.content.parts;
let fullText = "";
for (const part of geminiParts) {
  if (part.text) fullText += part.text;
}

if (fullText.length > 1900) {
  fullText = fullText.substring(0, 1900) + "\n\n*(truncated)*";
}

return [{ json: { content: fullText } }];
